-- Generated by scripts/build_compiled.py from src/fraudrules/rules/foreign-agent/fa-003-vague-purpose-no-documents.yaml. Do not edit.
-- FA-003 Third-party payment with a generic purpose and no invoice, contract or order on file
SELECT
  'FA-003' AS rule_id,
  'transactions' AS anchor_table,
  a.id AS anchor_id
FROM transactions AS a
WHERE
  (
    a.direction = 'out'
    AND NOT a.directing_agent_id IS NULL
    AND a.in_agent_agreement = 0
    AND (
      a.purpose IN ('settlement', 'services', 'business_expense') OR a.purpose IS NULL
    )
    AND (
      a.supporting_docs = 0 OR a.supporting_docs IS NULL
    )
  );
